#!/usr/bin/env python3
"""Generate the embedded, unmodified Monogram bitmap table."""
import json
from pathlib import Path
import sys

root = Path(__file__).resolve().parent
glyphs = json.loads((root / "monogram-bitmap.json").read_text())
entries = sorted((ord(character), rows) for character, rows in glyphs.items())
assert len(entries) == 390
assert all(code <= 0xffff and len(rows) == 12 and
           all(isinstance(row, int) and 0 <= row < 128 for row in rows)
           for code, rows in entries)
output = ["/* SPDX-License-Identifier: CC0-1.0",
          " * Generated by fonts/monogram/generate.py; do not edit glyphs here.",
          " * Monogram 1.1 by Vinícius Menézio: https://datagoblin.itch.io/monogram",
          " */", "static const struct monogram_glyph {",
          "    uint16_t codepoint;", "    uint8_t rows[12];",
          "} monogram_glyphs[] = {"]
for code, rows in entries:
    output.append("    {0x%04x, {%s}}," % (code, ",".join(map(str, rows))))
output.extend(["};", ""])
result = "\n".join(output)
target = root / "monogram-data.h"
if "--check" in sys.argv:
    assert target.read_text() == result, "Regenerate Monogram data"
else:
    target.write_text(result)
